WITH valid AS (SELECT id, customer_id, order_date, status, channel, amount, discount, shipping_fee, LEAST(shipping_fee, amount) AS least_shipping_fee_amount FROM orders WHERE shipping_fee >= 26) SELECT d.city, s.channel, COUNT(*) AS rows_total, ROUND(AVG(s.discount), 2) AS avg_discount FROM valid s INNER JOIN customers d ON s.customer_id = d.id GROUP BY GROUPING SETS ((d.city, s.channel), (d.city), ()) ORDER BY channel DESC NULLS LAST
